const binary = $input.item.binary?.file;

if (!binary) {
  return [{ json: { valid: false, statusCode: 400, error: 'No file uploaded. Expected a binary field named "file".' } }];
}

const allowedTypes = ['application/pdf'];
if (binary.mimeType && !allowedTypes.includes(binary.mimeType)) {
  return [{ json: { valid: false, statusCode: 400, error: `Unsupported file type: ${binary.mimeType}. Upload a PDF.` } }];
}

const maxBytes = 10 * 1024 * 1024; // 10MB
const size = binary.fileSize ? Number(binary.fileSize) : (binary.data ? Buffer.byteLength(binary.data, 'base64') : 0);
if (size > maxBytes) {
  return [{ json: { valid: false, statusCode: 400, error: 'File too large. Max 10MB.' } }];
}

const intent = $json.body?.intent;
if (!intent) {
  return [{ json: { valid: false, statusCode: 400, error: 'Missing "intent" in request body.' } }];
}

return [{ json: { valid: true }, binary: $input.item.binary }];

const rawText = $json.text;
const pages = Array.isArray(rawText) ? rawText : [String(rawText ?? '')];
const text = pages.map((page, i) => `--- PAGE ${i + 1} ---
${String(page ?? '')}`).join('

');
const trimmed = text.trim();

if (trimmed.length < 200) {
  return [{ json: { sane: false, reason: `Extracted text is only ${trimmed.length} characters — likely a scanned image PDF with no text layer, or an empty/corrupted file.` } }];
}

const alphanumeric = (trimmed.match(/[a-zA-Z0-9]/g) || []).length;
const ratio = alphanumeric / trimmed.length;
if (ratio < 0.5) {
  return [{ json: { sane: false, reason: 'Extracted text is mostly non-alphanumeric characters — likely a garbled or corrupted extraction.' } }];
}

return [{ json: { sane: true, text } }];

// Extract from File's error branch (exception thrown — e.g. encrypted PDF) and
// Sanity Check's false branch both land here via the same message shape, so
// they can share one response node downstream.
const reason = $json.reason
  || $json.error?.message
  || 'Could not read the uploaded PDF. It may be corrupted, password-protected, or not a real PDF.';

return [{
  json: {
    valid: false,
    statusCode: 422,
    needs_human_review: true,
    error: reason
  }
}];

// Orchestrator Agent's error branch — reached only after retries (3 tries,
// 2s apart) are exhausted. Typically a persistent Anthropic API error (rate
// limit, timeout, malformed output) rather than a one-off blip.
return [{
  json: {
    valid: false,
    statusCode: 502,
    needs_human_review: true,
    error: 'The extraction agent failed after 3 attempts. This usually means the LLM API is rate-limited, timing out, or returned output the parser could not use.'
  }
}];

let parsed;
const raw = $json.output ?? $json.text ?? '';
try {
  const match = String(raw).match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : raw);
} catch (e) {
  parsed = { contract_type: 'UNKNOWN', playbook_rules: [] };
}

return [{
  json: {
    contract_type: parsed.contract_type ?? 'UNKNOWN',
    playbook_rules: Array.isArray(parsed.playbook_rules) ? parsed.playbook_rules : []
  }
}];

// Self-consistency voting: run the extraction prompt N times independently at
// temperature > 0, then vote on the results downstream (Aggregate Self-Consistency
// Votes node). N=3 chosen as a cost/latency tradeoff — 3x the API calls and latency
// of a single extraction call, on a pipeline that already runs ~30-60s per document.
const N = 3;
const base = $json;
const items = [];
for (let i = 1; i <= N; i++) {
  items.push({
    json: {
      run_index: i,
      run_count: N,
      contract_type: base.contract_type,
      playbook_rules: base.playbook_rules,
      text: base.text
    }
  });
}
return items;

// Self-consistency vote: N independent extraction runs (see Prepare N Extraction
// Requests) land here as N items. For each playbook field, take the majority value
// across runs as the final answer, with agreement fraction as the confidence score
// (e.g. 3/3 = high confidence, 2/3 = lower). No majority at all (every run disagreed)
// is flagged as no_consensus regardless of risk_weight — handled as a forced review
// trigger in Parse Result, not here.
const runs = $input.all().map((item) => {
  const raw = item.json.completion ?? '';
  try {
    const match = String(raw).match(/\{[\s\S]*\}/);
    return JSON.parse(match ? match[0] : raw);
  } catch (e) {
    return { parties: [], effective_date: null, key_terms: [] };
  }
});

const N = runs.length;
const contractType = $input.all()[0]?.json?.contract_type ?? 'UNKNOWN';

function normalize(v) {
  return String(v ?? '').trim().toLowerCase().replace(/\s+/g, ' ');
}

const labelOrder = [];
const seenLabels = new Set();
for (const run of runs) {
  for (const t of (run.key_terms ?? [])) {
    if (t.label && !seenLabels.has(t.label)) {
      seenLabels.add(t.label);
      labelOrder.push(t.label);
    }
  }
}

const mergedKeyTerms = labelOrder.map((label) => {
  const entries = runs
    .map((run) => (run.key_terms ?? []).find((t) => t.label === label) ?? null)
    .filter(Boolean);

  const counts = new Map();
  for (const e of entries) {
    const key = normalize(e.value);
    if (!counts.has(key)) counts.set(key, { count: 0, sample: e });
    counts.get(key).count += 1;
  }

  let best = null;
  for (const v of counts.values()) {
    if (!best || v.count > best.count) best = v;
  }

  const topCount = best ? best.count : 0;
  const noConsensus = counts.size > 1 && topCount === 1;

  return {
    label,
    value: best ? best.sample.value : 'Not specified',
    risk_weight: best ? best.sample.risk_weight : (entries[0]?.risk_weight ?? null),
    source_quote: best ? best.sample.source_quote : null,
    clause_ref: best ? best.sample.clause_ref : null,
    page_number: best ? (best.sample.page_number ?? null) : null,
    reasoning: best ? (best.sample.reasoning ?? null) : null,
    confidence_fraction: `${topCount}/${N}`,
    confidence_ratio: N ? topCount / N : 0,
    no_consensus: noConsensus
  };
});

// Representative run for contract-level fields (parties, effective_date): the run
// whose own values agree with the merged key_terms the most.
function agreementScore(run) {
  let score = 0;
  for (const mt of mergedKeyTerms) {
    const rt = (run.key_terms ?? []).find((t) => t.label === mt.label);
    if (rt && normalize(rt.value) === normalize(mt.value)) score += 1;
  }
  return score;
}

let bestRun = runs[0] ?? { parties: [], effective_date: null };
let bestScore = -1;
for (const run of runs) {
  const s = agreementScore(run);
  if (s > bestScore) { bestScore = s; bestRun = run; }
}

return [{
  json: {
    contract_type: contractType,
    parties: bestRun.parties ?? [],
    effective_date: bestRun.effective_date ?? null,
    key_terms: mergedKeyTerms,
    self_consistency_runs: N
  }
}];

const parsed = $json;
const keyTerms = Array.isArray(parsed.key_terms) ? parsed.key_terms : [];

// GATE 2 — escalate to human review when any of:
//  (a) a term is BOTH high-stakes (risk_weight 4-5) AND unverified (no citation)
//  (b) the self-consistency vote found no consensus at all (every run disagreed) —
//      flagged regardless of risk_weight, since "the model can't agree with itself"
//      is its own reason for distrust
//  (c) a term is high-stakes (risk_weight 4-5) AND the self-consistency runs did not
//      unanimously agree (a majority exists, but it wasn't 3/3) — partial agreement
//      on a critical field is still real uncertainty worth a human's attention, even
//      when the majority answer happens to carry a citation. This matters most for
//      synthesized/summarized fields (e.g. "Loss History Summary") where disagreement
//      usually means real interpretive judgment was involved, not just a lookup.
const unverifiedHighRisk = keyTerms.filter(
  (t) => Number(t.risk_weight) >= 4 && (t.source_quote == null || String(t.source_quote).trim() === '')
);
const noConsensusTerms = keyTerms.filter((t) => t.no_consensus === true);
const partialAgreementHighRisk = keyTerms.filter(
  (t) => Number(t.risk_weight) >= 4 && !t.no_consensus && typeof t.confidence_ratio === 'number' && t.confidence_ratio < 1 && !unverifiedHighRisk.includes(t)
);
const flaggedTerms = [...new Set([...unverifiedHighRisk, ...noConsensusTerms, ...partialAgreementHighRisk])];
const needsHumanReview = flaggedTerms.length > 0;

const reasonParts = [];
if (unverifiedHighRisk.length > 0) {
  reasonParts.push(`${unverifiedHighRisk.length} high-risk term(s) could not be verified against the contract text: ${unverifiedHighRisk.map((t) => t.label).filter(Boolean).join(', ')}.`);
}
if (noConsensusTerms.length > 0) {
  reasonParts.push(`${noConsensusTerms.length} term(s) had no agreement across the ${parsed.self_consistency_runs ?? '?'} extraction runs: ${noConsensusTerms.map((t) => t.label).filter(Boolean).join(', ')}.`);
}
if (partialAgreementHighRisk.length > 0) {
  reasonParts.push(`${partialAgreementHighRisk.length} high-risk term(s) had only partial agreement (not unanimous) across the ${parsed.self_consistency_runs ?? '?'} extraction runs: ${partialAgreementHighRisk.map((t) => t.label).filter(Boolean).join(', ')}.`);
}
const reviewReason = reasonParts.length ? reasonParts.join(' ') : null;

return [{
  json: {
    session_id: $execution.id,
    contract_type: parsed.contract_type ?? 'UNKNOWN',
    parties: parsed.parties ?? [],
    effective_date: parsed.effective_date ?? null,
    key_terms: keyTerms,
    raw_response: parsed,
    model: 'claude-haiku-4-5-20251001',
    self_consistency_runs: parsed.self_consistency_runs ?? null,
    needs_human_review: needsHumanReview,
    review_reason: reviewReason
  }
}];

// Log Extraction to Supabase returns the inserted row (Prefer: return=representation).
// Deliberately NOT using $('Parse Result').item.json here — a cross-node lookup from
// inside Code-node JS hangs/errors on this instance's Task Runner (see README).
// Not needed anyway: every field below was already sent TO Supabase in the insert body,
// so the returned row already has all of it, available locally on $json with no
// cross-node call required.
const inserted = Array.isArray($json) ? $json[0] : $json;

return [{
  json: {
    id: inserted?.id ?? null,
    contract_type: inserted?.contract_type ?? 'UNKNOWN',
    parties: inserted?.parties ?? [],
    effective_date: inserted?.effective_date ?? null,
    key_terms: inserted?.key_terms ?? [],
    self_consistency_runs: inserted?.self_consistency_runs ?? null,
    needs_human_review: inserted?.needs_human_review ?? false,
    review_reason: inserted?.review_reason ?? null
  }
}];
